import $ from "../../../../core/renderer";
import {
    EmptyTemplate
} from "../../../core/templates/m_empty_template";
import {
    AppointmentCollector
} from "../appointment_collector";
export const getAppointmentCollectorProperties = appointmentsData => {
    const targetedAppointmentData = Object.assign({}, appointmentsData[0], {
        displayStartDate: appointmentsData[0].startDate,
        displayEndDate: appointmentsData[0].endDate
    });
    const config = {
        tabIndex: 0,
        sortedIndex: 0,
        appointmentsData: appointmentsData,
        isCompact: false,
        geometry: {
            height: 30,
            width: 30,
            top: 0,
            left: 0
        },
        targetedAppointmentData: targetedAppointmentData,
        appointmentCollectorTemplate: new EmptyTemplate,
        onFocusIn: () => {},
        onFocusOut: () => {},
        onKeyDown: () => {},
        onClick: () => {}
    };
    return config
};
export const createAppointmentCollector = properties => {
    const $element = $(".root");
    return new AppointmentCollector($element, properties)
};
